/bin/bash -lc "python3 - <<'PY'
import os, sqlite3, tempfile, subprocess, shutil, pathlib, textwrap
base='/tmp/zkprobe10.zgg5y7lb/.zk'
d=tempfile.mkdtemp(prefix='/tmp/zktemplateprobe2.')
os.makedirs(os.path.join(d,'.zk','templates'))
pathlib.Path(os.path.join(d,'.zk','config.toml')).write_text(pathlib.Path(os.path.join(base,'config.toml')).read_text())
pathlib.Path(os.path.join(d,'.zk','templates','default.md')).write_text(textwrap.dedent('''\\
TITLE={{title}}
CONTENT={{content}}
ID={{id}}
NOW={{now}}
SLUG={{slug title}}
EXTRA={{extra.foo}}
FMT1={{format-date now}}
FMT2={{format-date now \"2006-01-02\"}}
PATH={{path}}
LINK={{link}}
'''))
con=sqlite3.connect(os.path.join(d,'.zk','notebook.db'))
cur=con.cursor(); cur.execute('PRAGMA user_version=999')
cur.execute('CREATE TABLE metadata(key TEXT PRIMARY KEY, value TEXT)')
cur.execute('''CREATE TABLE notes(id INTEGER PRIMARY KEY,path TEXT UNIQUE,sortable_path TEXT,filename TEXT,title TEXT,lead TEXT,body TEXT,raw_content TEXT,word_count INTEGER,metadata TEXT,checksum TEXT,created TIMESTAMP,modified TIMESTAMP)''')
cur.execute('''CREATE TABLE links(id INTEGER PRIMARY KEY,source_id INTEGER,target_id INTEGER,title TEXT,href TEXT,type TEXT,external INTEGER,rels TEXT,snippet TEXT,snippet_start INTEGER,snippet_end INTEGER)''')
cur.execute('''CREATE TABLE collections(id INTEGER PRIMARY KEY,kind TEXT,name TEXT)''')
cur.execute('''CREATE TABLE notes_collections(id INTEGER PRIMARY KEY,note_id INTEGER,collection_id INTEGER)''')
cur.execute('''CREATE VIEW resolved_links AS SELECT l.id,s.path AS source_path,t.path AS target_path,l.source_id,l.target_id,l.title,l.href,l.type,l.external,l.rels,l.snippet,l.snippet_start,l.snippet_end FROM links l LEFT JOIN notes s ON s.id=l.source_id LEFT JOIN notes t ON t.id=l.target_id''')
cur.execute('''CREATE VIEW notes_with_metadata AS SELECT n.*,COALESCE(GROUP_CONCAT(c.name,' '),'') AS tags FROM notes n LEFT JOIN notes_collections nc ON nc.note_id=n.id LEFT JOIN collections c ON c.id=nc.collection_id AND c.kind='tag' GROUP BY n.id''')
con.commit(); con.close()
p=subprocess.run(['/workspace/executable','--working-dir',d,'new','--dry-run','--title','Hello World','--extra','foo=bar'],capture_output=True,text=True)
print('RC',p.returncode)
print('STDOUT\\n'+p.stdout)
print('STDERR\\n'+p.stderr)
PY"

